// PartHub brand: the logo mark (a "P" whose bowl is a gear, one tooth in
// electric blue) and the official colors. Guidelines: infra/docs/brand.md.
// SVG masters: infra/brand/. The paths are generated by
// infra/brand/generate.py; change them there, not by hand.

export const BRAND_COLORS = {
  navy: "#102D4B",
  electric: "#2875E5",
  electricOnDark: "#5B9BFF",
  charcoal: "#111827",
  white: "#FFFFFF",
};

const RING = "M52.5,27A16.5,16.5 0 1 0 19.5,27A16.5,16.5 0 1 0 52.5,27ZM44.5,27A8.5,8.5 0 1 1 27.5,27A8.5,8.5 0 1 1 44.5,27Z";
const BODY = "M12,8H23V50L12,58ZM38.42,11.69L40.90,6.58L46.97,9.09L45.11,14.46ZM51.31,29.42L56.42,31.90L53.91,37.97L48.54,36.11ZM45.11,39.54L46.97,44.91L40.90,47.42L38.42,42.31ZM33.58,42.31L31.10,47.42L25.03,44.91L26.89,39.54ZM23.46,36.11L18.09,37.97L15.58,31.90L20.69,29.42ZM20.69,24.58L15.58,22.10L18.09,16.03L23.46,17.89ZM26.89,14.46L25.03,9.09L31.10,6.58L33.58,11.69Z";
const ACCENT = "M48.54,17.89L53.91,16.03L56.42,22.10L51.31,24.58Z";

const VARIANTS = {
  color: [BRAND_COLORS.navy, BRAND_COLORS.electric],
  white: [BRAND_COLORS.white, BRAND_COLORS.electricOnDark],
  mono: [BRAND_COLORS.charcoal, BRAND_COLORS.charcoal],
};

// variant: "color" on light backgrounds, "white" on dark ones, "mono" for
// one-color print. Decorative by default (the name is next to it).
export function LogoMark({ variant = "color", className = "h-10 w-10", title }) {
  const [main, accent] = VARIANTS[variant] || VARIANTS.color;
  return (
    <svg viewBox="0 0 64 64" className={className} role={title ? "img" : undefined} aria-hidden={title ? undefined : "true"} aria-label={title}>
      <path fill={main} fillRule="evenodd" d={RING} />
      <path fill={main} d={BODY} />
      <path fill={accent} d={ACCENT} />
    </svg>
  );
}

// "PartHub" with "Hub" in the accent color. onDark: white + light blue.
export function LogoWordmark({ onDark = false, className = "" }) {
  return (
    <span className={`font-sans font-bold leading-none tracking-[-0.01em] ${className}`} style={{ color: onDark ? BRAND_COLORS.white : BRAND_COLORS.navy }}>
      Part<span style={{ color: onDark ? "#9CC0FF" : BRAND_COLORS.electric }}>Hub</span>
    </span>
  );
}
